-- G29 / F35 (decision in docs/STATUS.md, G29 perfil): health-area reference data in production. Before this, the tables were filled only by `pnpm db:seed`
-- (dev), so /v1/public/reference/* answered [] in production: no courses, no goals, no institutions. Idempotent upserts,
-- generated from packages/db/seed/reference/*.json (same rows the seed loader writes; the seed stays for refreshing them).
-- health_courses: exactly the ten courses + not_health (Fernando, G29); rows outside the list are removed (no FK points at
-- health_courses: study_profiles.course_code has only a CHECK, its codes stay valid). Down: nothing to undo (reference data).
--> statement-breakpoint
ON CONFLICT (code) DO UPDATE SET name = excluded.name;
--> statement-breakpoint
ON CONFLICT (code) DO UPDATE SET name = excluded.name, aliases = excluded.aliases, kind = excluded.kind, council_code = excluded.council_code, suggested_goals = excluded.suggested_goals, sort = excluded.sort;
--> statement-breakpoint
DELETE FROM public.health_courses WHERE code NOT IN ('medicine', 'nursing', 'dentistry', 'pharmacy', 'physiotherapy', 'nutrition', 'psychology', 'physical_education', 'biomedicine', 'veterinary_medicine', 'not_health');
--> statement-breakpoint
ON CONFLICT (code) DO UPDATE SET name = excluded.name, course_codes = excluded.course_codes, sort = excluded.sort;
--> statement-breakpoint
-- Source: INEP, Censo da Educação Superior 2024 (CO_IES = e-MEC code); see packages/db/seed/reference/SOURCES.md.
ON CONFLICT (emec_code) DO UPDATE SET name = excluded.name, acronym = excluded.acronym, city = excluded.city, uf = excluded.uf, type = excluded.type, search = excluded.search, updated_at = now();
